+      drawerBackdrop?.addEventListener('click', closeDrawer);
+      drawerCloseBtn?.addEventListener('click', closeDrawer);
+      qsa('[data-drawer-link]').forEach((a) => a.addEventListener('click', closeDrawer));
+      window.addEventListener('keydown', (e) => {
+        if (e.key === 'Escape' && document.body.classList.contains('drawer-open')) closeDrawer();
+      });
+
+      // --- Autocomplete (snappy, accessible) ---
+      const qInput = qs('#q');
+      const ac = qs('#ac');
+      const acList = qs('#acList');
+      const acClose = qs('#acClose');
+
+      const suggestions = [
+        { type: 'Specialty', label: 'Dentist' },
+        { type: 'Specialty', label: 'Primary Care' },
+        { type: 'Specialty', label: 'Dermatologist' },
+        { type: 'Specialty', label: 'Psychiatrist' },
+        { type: 'Specialty', label: 'Eye Doctor' },
+        { type: 'Specialty', label: 'Orthopedic Surgeon' },
+        { type: 'Condition', label: 'Back pain' },
+        { type: 'Condition', label: 'Acne' },
+        { type: 'Condition', label: 'Anxiety' },
