+      });
+
+      qInput?.addEventListener('focus', () => {
+        refreshAutocomplete();
+      });
+
+      qInput?.addEventListener('keydown', (e) => {
+        if (!acOpen && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) {
+          refreshAutocomplete();
+        }
+        if (!acOpen) return;
+
+        const options = qsa('.ac-item', acList);
+        if (e.key === 'Escape') {
+          setAcOpen(false);
+          return;
+        }
+        if (e.key === 'ArrowDown') {
+          e.preventDefault();
+          updateSelection(Math.min(options.length - 1, acIndex + 1));
+        }
+        if (e.key === 'ArrowUp') {
+          e.preventDefault();
+          updateSelection(Math.max(0, acIndex - 1));
+        }
