+            setAcOpen(false);
+          }
+        }
+      });
+
+      document.addEventListener('click', (e) => {
+        if (!acOpen) return;
+        const within = ac.contains(e.target) || qInput.contains(e.target);
+        if (!within) setAcOpen(false);
+      });
+      acClose?.addEventListener('click', () => setAcOpen(false));
+
+      // --- Geolocation button (optional enhancement) ---
+      const geoBtn = qs('#geoBtn');
+      const locInput = qs('#loc');
+      geoBtn?.addEventListener('click', async () => {
+        if (!('geolocation' in navigator)) {
+          locInput?.focus();
+          return;
+        }
+
+        geoBtn.disabled = true;
