+          await new Promise((resolve, reject) => {
+            navigator.geolocation.getCurrentPosition(resolve, reject, { enableHighAccuracy: false, timeout: 6000 });
+          });
+          // No reverse geocode without external API; use friendly confirmation.
+          locInput.value = 'Current location';
+        } catch {
+          // Ignore; user denied or timed out
+        } finally {
+          geoBtn.disabled = false;
+          geoBtn.style.opacity = '1';
+          geoBtn.style.cursor = 'pointer';
+          locInput?.focus();
+        }
+      });
+
+      // --- Search form submission (demo navigation) ---
+      const searchForm = qs('#searchForm');
+      searchForm?.addEventListener('submit', (e) => {
