+        window.location.href = `search-results.html?${params.toString()}`;
+      });
+
+      // --- Specialty cards click tracking (still real link) ---
+      qsa('[data-specialty]').forEach((card) => {
+        card.addEventListener('click', () => {
+          // Keep as a no-op for now; href handles navigation.
+        });
+      });
