+      qs('#loginForm')?.addEventListener('submit', (e) => {
+        e.preventDefault();
+        toast(qs('#loginToast'), 'Demo only — login is not connected.');
+      });
+      qs('#signupForm')?.addEventListener('submit', (e) => {
+        e.preventDefault();
+        toast(qs('#signupToast'), 'Demo only — account creation is not connected.');
+      });
+    </script>
